211	FText UViewModeUtils::GetViewModeDisplayName(const EViewModeIndex ViewModeIndex)
212	{
213		const FText ViewModeName = GViewModeDisplayNames[ViewModeIndex];
214		ensureMsgf(!ViewModeName.IsEmpty(), TEXT("Used an unknown value of EViewModeIndex (with value %d). Consider adding this new value in UViewModeUtils::GetViewModeName"), ViewModeIndex);
215		return ViewModeName;
216	}
