26	 * Enumeration for different Quad Overdraw visualization mode.
27	 */
28	enum EDebugViewShaderMode
29	{
30		DVSM_None,						// No debug view.
31		DVSM_ShaderComplexity,			// Default shader complexity viewmode
32		DVSM_ShaderComplexityContainedQuadOverhead,	// Show shader complexity with quad overdraw scaling the PS instruction count.
33		DVSM_ShaderComplexityBleedingQuadOverhead,	// Show shader complexity with quad overdraw bleeding the PS instruction count over the quad.
34		DVSM_QuadComplexity,			// Show quad overdraw only.
35		DVSM_PrimitiveDistanceAccuracy,	// Visualize the accuracy of the primitive distance computed for texture streaming.
36		DVSM_MeshUVDensityAccuracy,		// Visualize the accuracy of the mesh UV densities computed for texture streaming.
37		DVSM_MaterialTextureScaleAccuracy, // Visualize the accuracy of the material texture scales used for texture streaming.
38		DVSM_OutputMaterialTextureScales,  // Outputs the material texture scales.
39		DVSM_RequiredTextureResolution, // Visualize the accuracy of the streamed texture resolution.
40		DVSM_VirtualTexturePendingMips,	// Visualize the pending virtual texture mips.
41		DVSM_LODColoration,				// Visualize primitive LOD .
42		DVSM_VisualizeGPUSkinCache,		// Visualize various properties of Skin Cache.
43		DVSM_VisualizeMaterialAO,		// Visualize native material ao
44		DVSM_TextureDensity,				// Visualize material texture density in texels per meter.
45		DVSM_MAX
46	};
