float GetUVDensityColorationThreshold(int Index)
{
	if (Index == 0)
	{
		return UVDensityColorationThresholds[0].x;
	}
	if (Index == 1)
	{
		return UVDensityColorationThresholds[0].y;
	}
	if (Index == 2)
