float GetUVDensityColorationIndex(float DensityTexelsPerMeter)
{
	float SafeDensity = max(DensityTexelsPerMeter, 0.0001f);
	float PreviousThreshold = max(GetUVDensityColorationThreshold(0), 0.0001f);
	if (SafeDensity <= PreviousThreshold)
	{
		return 0.001f;
	}

	UNROLL
	for (int ThresholdIndex = 1; ThresholdIndex < 8; ++ThresholdIndex)
	{
		float NextThreshold = max(GetUVDensityColorationThreshold(ThresholdIndex), PreviousThreshold + 0.0001f);
		if (SafeDensity <= NextThreshold)
		{
			float PreviousLog = log2(PreviousThreshold);
			float NextLog = log2(NextThreshold);
			float DensityLog = log2(SafeDensity);
			return clamp((float)(ThresholdIndex - 1) + (DensityLog - PreviousLog) / max(NextLog - PreviousLog, 0.0001f), 0.001f, 6.998f);
		}
		PreviousThreshold = NextThreshold;
	}

	return 6.998f;
}

void AccumulateUVDensity(float DensityTexelsPerMeter, float Weight)
{
	float SampleWeight = saturate(Weight);
	if (SampleWeight <= 0.001f)
	{
		return;
	}

	GUVDensityTexelsPerMeterSum += max(DensityTexelsPerMeter, 0.0f) * SampleWeight;
