void GetUVDensityColorationSettings(FLinearColor OutColors[NumUVDensityColorationColors], float OutValues[NumUVDensityColorationColors])
{
	static const FLinearColor DefaultColors[NumUVDensityColorationColors] =
	{
		FLinearColor(0.0f, 0.0f, 0.1f, 1.0f),
		FLinearColor(0.1f, 0.1f, 0.4f, 1.0f),
		FLinearColor(0.0f, 0.1f, 0.0f, 1.0f),
		FLinearColor(0.0f, 0.5f, 0.0f, 1.0f),
		FLinearColor(0.5f, 0.5f, 0.0f, 1.0f),
		FLinearColor(0.6f, 0.0f, 0.0f, 1.0f),
		FLinearColor(0.6f, 0.0f, 0.6f, 1.0f),
		FLinearColor(1.0f, 1.0f, 1.0f, 1.0f)
	};
	static const float DefaultValues[NumUVDensityColorationColors] =
	{
		25.0f,
		50.0f,
		100.0f,
		200.0f,
		400.0f,
		800.0f,
		1600.0f,
		3200.0f
	};

	for (int32 Index = 0; Index < NumUVDensityColorationColors; ++Index)
	{
		OutColors[Index] = DefaultColors[Index];
		OutValues[Index] = DefaultValues[Index];
	}

	const URendererSettings* Settings = GetDefault<URendererSettings>();
	if (!Settings)
	{
		return;
	}

	const int32 NumSettings = FMath::Min(Settings->TextureDensityDebugColoration.Num(), NumUVDensityColorationColors);
	float PreviousValue = 0.0f;
	for (int32 Index = 0; Index < NumSettings; ++Index)
	{
		const FTextureDensityDebugColorationEntry& Entry = Settings->TextureDensityDebugColoration[Index];
		OutColors[Index] = Entry.Color;
		OutValues[Index] = FMath::Max(Entry.TexelsPerMeter, PreviousValue + UE_SMALL_NUMBER);
		PreviousValue = OutValues[Index];
	}

	for (int32 Index = NumSettings; Index < NumUVDensityColorationColors; ++Index)
	{
		OutValues[Index] = FMath::Max(OutValues[Index], PreviousValue + UE_SMALL_NUMBER);
		PreviousValue = OutValues[Index];
	}
}

