508	void FMaterialRenderProxy::InvalidateUniformExpressionCache(bool bRecreateUniformBuffer)
509	{
510		GUniformExpressionCacheAsyncUpdateTask.Wait();
511	
512	#if WITH_EDITOR
513		FStaticLightingSystemInterface::OnMaterialInvalidated.Broadcast(this);
514	#endif
