171	static bool TickUVDensityLODColorationShaderPrecompile(float DeltaTime)
172	{
173	#if WITH_DEBUG_VIEW_MODES && WITH_EDITORONLY_DATA
174		const int32 BatchSize = FMath::Max(1, CVarUVDensityDebugViewShaderPrecompileBatchSize.GetValueOnGameThread());
175	
176		TSet<UMaterialInterface*> MaterialsToSubmit;
177		while (MaterialsToSubmit.Num() < BatchSize && GUVDensityLODColorationQueuedMaterials.Num() > 0)
178		{
179			const FUVDensityLODColorationMaterialEntry Entry = GUVDensityLODColorationQueuedMaterials.Pop(EAllowShrinking::No);
180			GUVDensityLODColorationQueuedMaterialKeys.Remove(Entry.Key);
181	
182			if (UMaterialInterface* MaterialInterface = Entry.Material.Get())
183			{
184				MaterialsToSubmit.Add(MaterialInterface);
185			}
186		}
187	
188		if (MaterialsToSubmit.Num() > 0)
189		{
190			TSet<UMaterialInterface*> PendingMaterials;
191			BeginCompileDebugViewModeShaders(
192				DVSM_TextureDensity,
193				GetCachedScalabilityCVars().MaterialQualityLevel,
194				GMaxRHIFeatureLevel,
195				MaterialsToSubmit,
196				&PendingMaterials);
197	
198			for (UMaterialInterface* PendingMaterial : PendingMaterials)
199			{
200				AddUVDensityLODColorationPendingMaterial(PendingMaterial);
201			}
202		}
203	
204		int32 NumPendingMaterialsPolled = 0;
205		for (int32 PendingIndex = GUVDensityLODColorationPendingMaterials.Num() - 1; PendingIndex >= 0 && NumPendingMaterialsPolled < BatchSize; --PendingIndex)
206		{
207			++NumPendingMaterialsPolled;
208	
209			UMaterialInterface* MaterialInterface = GUVDensityLODColorationPendingMaterials[PendingIndex].Material.Get();
210			if (!MaterialInterface)
211			{
212				RemoveUVDensityLODColorationMaterialEntry(GUVDensityLODColorationPendingMaterials, GUVDensityLODColorationPendingMaterialKeys, PendingIndex);
213				continue;
214			}
215	
216			FMaterial* Material = MaterialInterface->GetMaterialResource(GMaxRHIFeatureLevel, GetCachedScalabilityCVars().MaterialQualityLevel);
217			if (!Material || Material->IsCompilationFinished())
218			{
219				RemoveUVDensityLODColorationMaterialEntry(GUVDensityLODColorationPendingMaterials, GUVDensityLODColorationPendingMaterialKeys, PendingIndex);
220			}
221		}
222	
223		if (GUVDensityLODColorationQueuedMaterials.Num() == 0 && GUVDensityLODColorationPendingMaterials.Num() == 0)
224		{
225			GUVDensityLODColorationShaderTickerHandle.Reset();
226			return false;
227		}
228	
229		return true;
230	#else
231		GUVDensityLODColorationShaderTickerHandle.Reset();
232		return false;
233	#endif
